// Cruza cada fila (por lead_id) contra la lista de cuentas abiertas
// (panel_conversions, deposit_status=ACCOUNT_CREATED). Una sola
// consulta MySQL por corrida, no una por fila.
const openedIds = new Set(
  $('🏦 Cuentas Abiertas (lookup)').all().map(i => String(i.json.lead_id))
);

const row = $json;
const leadId = String(row._lead_id || '');
const accountOpened = leadId && openedIds.has(leadId) ? 'Yes' : '';

const out = { ...row };
delete out._lead_id;  // interno, no va a la hoja
out['Account Opened'] = accountOpened;
return { json: out };

const startOfDay = $now.setZone('Asia/Kolkata').startOf('day');
const nowIST = $now.setZone('Asia/Kolkata');

return [{
  json: {
    start_unix: Math.floor(startOfDay.toSeconds()),
    end_unix: Math.floor(nowIST.toSeconds()),
    date_str: startOfDay.toFormat('yyyy-MM-dd')
  }
}];

const listItem = $('Agregar País (por agent_id)').item.json;
const country = listItem._country || 'india';
const detail = $json;

const durSecs = listItem.call_duration_secs || 0;

const dynVars = detail.conversation_initiation_client_data?.dynamic_variables
             || detail.metadata?.dynamic_variables || {};
const phone = dynVars.phone || detail.user_id || listItem.phone || 'N/A';
// ⚠️ Verificar el nombre real del campo en dynamic_variables — se
// asume 'lead_id' por consistencia con WF9. Ajustar si no matchea.
const leadId = dynVars.lead_id || listItem.lead_id || '';
const summary = listItem.transcript_summary || detail.analysis?.transcript_summary || '';

const startUnix = listItem.start_time_unix_secs;
const utcDate = new Date(startUnix * 1000);
const istOffset = 5.5 * 60 * 60 * 1000;
const istDate = new Date(utcDate.getTime() + istOffset);

const yyyy = istDate.getUTCFullYear();
const mm = String(istDate.getUTCMonth() + 1).padStart(2, '0');
const dd = String(istDate.getUTCDate()).padStart(2, '0');
const fecha = `${dd}/${mm}/${yyyy}`;

const hh = String(istDate.getUTCHours()).padStart(2, '0');
const min = String(istDate.getUTCMinutes()).padStart(2, '0');
const ss = String(istDate.getUTCSeconds()).padStart(2, '0');
const hora = `${hh}:${min}:${ss}`;

// Duración en segundos puros (número, no texto) para poder
// filtrar/ordenar numéricamente en Sheets — antes era '1m 47s'.
const duracion = durSecs;

// 'Account Opened' se llena en el nodo siguiente (🏦 Marcar cuentas
// abiertas), que cruza por lead_id contra panel_conversions (MySQL).
// Acá solo se deja preparado el lead_id para ese cruce.
return {
  json: {
    'Title / Number': listItem.call_summary_title || listItem.agent_name || '',
    'Date': fecha,
    'Time': hora,
    'Duration': duracion,
    'Customer Phone': phone,
    'Summary': summary,
    'Country': country.toUpperCase(),
    '_lead_id': leadId
  }
};

const found = $input.first().json;
const originalBinary = $('Convert to XLSX [IN]').first().binary;

return [{
  json: { folderId: found.id },
  binary: originalBinary
}];

const created = $input.first().json;
const originalBinary = $('Convert to XLSX [IN]').first().binary;

return [{
  json: { folderId: created.id },
  binary: originalBinary
}];

const searchResult = $input.first().json;
const found = searchResult && searchResult.id;

let folderData;
try {
  folderData = $('Use Existing Folder ID [IN]').first();
} catch (e) {
  folderData = null;
}
if (!folderData) {
  try {
    folderData = $('Use New Folder ID [IN]').first();
  } catch (e) {
    folderData = null;
  }
}

const outJson = { folderId: folderData.json.folderId };
if (found) outJson.reportFileId = found;

return [{ json: outJson, binary: folderData.binary }];

